<script setup>const p=defineProps({status:{default:'pending'},label:String,showLabel:{default:true}});const states={pending:['Pendiente','hollow','var(--text-muted)'],started:['Iniciado','ring','var(--action-primary)'],partial:['Parcial','half','var(--progress-complete)'],complete:['Completado','full','var(--progress-complete)'],adapted:['Adaptado','full','var(--progress-adapted)'],postponed:['Pospuesto','ring','var(--accent-focus)'],paused:['Pausado','bar','var(--progress-paused)'],resumed:['Retomado','full','var(--progress-resumed)'],skipped:['Omitido','dashed','var(--text-muted)'],none:['Sin registro','hollow','var(--text-muted)']};const s=()=>states[p.status]||states.pending</script>
<template><span class="a-status" :class="{'a-status--mark':!showLabel}" :style="{'--c':s()[2]}"><i :class="`a-status__${s()[1]}`"/><span :class="{'sr-only':!showLabel}">{{label||s()[0]}}</span></span></template>
<style scoped>.a-status{display:inline-flex;align-items:center;gap:8px;min-height:26px;padding:2px 10px 2px 8px;border:1px solid var(--border-subtle);border-radius:var(--radius-pill);color:var(--text-secondary);font:600 12px/1 var(--font-core)}.a-status--mark{padding:0;border:0}.a-status i{display:block;flex:none;width:10px;height:10px;border-radius:3px}.a-status__full{background:var(--c)}.a-status__hollow{border:1px solid var(--border-strong)}.a-status__ring{border:2px solid var(--c)}.a-status__dashed{border:1px dashed var(--c)}.a-status__bar{height:4px!important;border-radius:99px!important;background:var(--c)}.a-status__half{border:1px solid var(--c);background:linear-gradient(var(--c) 50%,transparent 50%)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}</style>
